var report="Tools/UI/CooldownBlackVerification.txt";System.IO.File.WriteAllText(report,"Cooldown background check\n");int frame=-1,wait=0;double started=UnityEditor.EditorApplication.timeSinceStartup;UnityEditor.EditorApplication.CallbackFunction tick=null;
System.Action finish=()=>{UnityEditor.EditorApplication.update-=tick;UnityEditor.EditorApplication.isPlaying=false;};
tick=()=>{try{if(!UnityEditor.EditorApplication.isPlaying)return;UnityEngine.Application.runInBackground=true;if(UnityEditor.EditorApplication.timeSinceStartup-started>60)throw new System.Exception("timeout");if(frame==UnityEngine.Time.frameCount)return;frame=UnityEngine.Time.frameCount;var m=UpgradeManager.Instance;var hud=UpgradeCooldownHud.FindInScene();if(m==null||hud==null||++wait<15)return;hud.Initialize(m);hud.Track(400);var images=hud.GetComponentsInChildren<UnityEngine.UI.Image>(true);var back=images.First(x=>x.name=="Cooldown_400");var shade=images.First(x=>x.name=="CooldownShade");if(back.color!=UnityEngine.Color.black||shade.color!=new UnityEngine.Color(0f,0f,0f,0.3f))throw new System.Exception("background="+back.color+" shade="+shade.color);System.IO.File.AppendAllText(report,"PASS background opaque black and shade black with 30 percent alpha\nCOMPLETE\n");finish();}catch(System.Exception e){System.IO.File.AppendAllText(report,"FAIL "+e+"\n");finish();}};UnityEditor.EditorApplication.update+=tick;UnityEditor.EditorApplication.isPlaying=true;return "Running cooldown color check";
